script:
(function () {
  'use strict';
  // Gordon (constant) growth dividend discount model.
  //   D1 = D0 x (1 + g)  (or D1 entered directly)
  //   Price:           P0 = D1 / (r - g)            requires r > g
  //   Required return: r  = D1 / P0 + g
  //   Growth rate:     given D1: g = r - D1 / P0
  //                    given D0: P0 = D0(1+g)/(r-g)  =>  g = (P0 x r - D0) / (P0 + D0)
  //   Dividend yield = D1 / P0; capital gains yield = g; price after t years = P0 x (1+g)^t;
  //   dividend in year t = D1 x (1+g)^(t-1).
  // Verified (scratch Node test): D0 $2.00, g 5%, r 10% -> D1 $2.10, P0 $42.00; textbook case
  // D0 $1.15, g 8%, r 13.4% -> D1 $1.242, P0 $23.00. Reverse solves: P0 $42, D0 $2, g 5% -> r 10.00%;
  // P0 $42, D0 $2, r 10% -> g 5.00%; P0 $23, D1 $1.242, r 13.4% -> g 8.00%.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var money4 = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 4 });
  var TITLES = { price: 'Value per share (P0)', ret: 'Required return (r)', growth: 'Implied growth rate (g)' };

  function num(id) {
    var el = document.getElementById(id);
    var v = el ? parseFloat(el.value) : NaN;
    return isNaN(v) ? NaN : v;
  }
  function pct(v) { return isFinite(v) ? (v * 100).toFixed(2) + '%' : '–'; }

  // Returns { P0, D1, r, g } or { error }.
  function solve(solveFor, divType, div, g, r, price) {
    if (solveFor === 'price') {
      if (!(r > g)) return { error: 'The required return must be higher than the growth rate.' };
      var D1 = divType === 'd1' ? div : div * (1 + g);
      return { P0: D1 / (r - g), D1: D1, r: r, g: g };
    }
    if (solveFor === 'ret') {
      var D1r = divType === 'd1' ? div : div * (1 + g);
      return { P0: price, D1: D1r, r: D1r / price + g, g: g };
    }
    var gg = divType === 'd1' ? r - div / price : (price * r - div) / (price + div);
    if (!(gg > -1)) return { error: 'These inputs imply a growth rate below -100%. Check the price and dividend.' };
    return { P0: price, D1: divType === 'd1' ? div : div * (1 + gg), r: r, g: gg };
  }

  var OUT = ['cgMain', 'cgD1', 'cgYield', 'cgCapYield', 'cgFuture'];

  function clear() {
    OUT.forEach(function (id) { document.getElementById(id).textContent = '–'; });
    document.getElementById('cgTable').innerHTML = '';
  }

  function update() {
    var solveFor = document.getElementById('cgSolve').value;
    var divType = document.getElementById('cgDivType').value;
    document.getElementById('cgPriceWrap').hidden = solveFor === 'price';
    document.getElementById('cgReturnWrap').hidden = solveFor === 'ret';
    document.getElementById('cgGrowthWrap').hidden = solveFor === 'growth';
    document.getElementById('cgMainLabel').textContent = TITLES[solveFor] || TITLES.price;
    var div = num('cgDividend'), g = num('cgGrowth') / 100, r = num('cgReturn') / 100, price = num('cgPrice');
    var years = Math.round(num('cgYears'));
    var error = document.getElementById('cgError');
    var msg = '';
    if (isNaN(div) || div <= 0) msg = 'Enter a dividend per share above 0.';
    else if (solveFor !== 'growth' && (isNaN(g) || g <= -1 || g > 1)) msg = 'Enter a growth rate above -100% and up to 100%.';
    else if (solveFor !== 'ret' && (isNaN(r) || r <= -1 || r > 1)) msg = 'Enter a required return above -100% and up to 100%.';
    else if (solveFor !== 'price' && (isNaN(price) || price <= 0)) msg = 'Enter a share price above 0.';
    else if (isNaN(years) || years < 1 || years > 50) msg = 'Projection years must be from 1 to 50.';
    var res = msg ? null : solve(solveFor, divType, div, g, r, price);
    if (res && res.error) msg = res.error;
    if (!msg && ![res.P0, res.D1, res.r, res.g].every(isFinite)) msg = 'These inputs do not give a finite result.';
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) { clear(); return; }

    document.getElementById('cgMain').textContent = solveFor === 'price' ? money.format(res.P0) : pct(solveFor === 'ret' ? res.r : res.g);
    document.getElementById('cgD1').textContent = money4.format(res.D1);
    document.getElementById('cgYield').textContent = pct(res.D1 / res.P0);
    document.getElementById('cgCapYield').textContent = pct(res.g);
    document.getElementById('cgFutureLabel').textContent = 'Projected price in year ' + years;
    document.getElementById('cgFuture').textContent = money.format(res.P0 * Math.pow(1 + res.g, years));
    var rows = [], cum = 0;
    for (var t = 1; t <= years; t++) {
      var d = res.D1 * Math.pow(1 + res.g, t - 1);
      var p = res.P0 * Math.pow(1 + res.g, t);
      cum += d;
      rows.push('<tr><td>' + t + '</td><td>' + money4.format(d) + '</td><td>' + money.format(cum) + '</td><td>' + money.format(p) + '</td></tr>');
    }
    document.getElementById('cgTable').innerHTML = rows.join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('cgForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
